-- Node: dnb-start (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":1,"title":"Dental / Intraoral Nerve Blocks — ED Procedure","body":"[Open visual guide: anatomy and illustrated procedures](#/info/dnb-visual-guide)\n\nIntraoral regional anesthesia controls odontogenic (toothache) pain, anesthetizes for dental fracture/avulsion management, and enables repair of intraoral and dentoalveolar lacerations — often more effective and humane than systemic analgesia alone.\n\nKey principle: the maxillary teeth (V2) are usually anesthetized by SUPRAPERIOSTEAL infiltration or superior-alveolar blocks because maxillary bone is porous; the mandibular teeth (V3) require an INFERIOR ALVEOLAR NERVE BLOCK because dense cortical bone blocks infiltration.\n\nOpen first:\n- [Contraindications + pre-procedure checks](#/node/dnb-contra)\n- [Shared technique for all intraoral blocks](#/node/dnb-shared-technique)\n- [Procedure Steps Summary](#/info/dnb-steps)\n- [Stop / Pitfalls](#/info/dnb-stop)\n- Tools: [Max LA Dose](#/calculator/dnb-la-max-dose) and [Block Selector](#/calculator/dnb-block-selector) in the toolbar\n\nThen select which tooth or region needs anesthesia.","citation":[1,2,6],"next":"dnb-region","summary":"Maxillary teeth (V2) = supraperiosteal/superior-alveolar (porous bone). Mandibular teeth (V3) = inferior alveolar block (dense bone).","safetyLevel":"warning"}'::jsonb
WHERE id = 'dnb-start' AND tree_id = 'dental-nerve-blocks';

-- Node: dnb-region (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"question","module":1,"title":"Which Tooth or Region Needs Anesthesia?","body":"[Open visual guide: anatomy and illustrated procedures](#/info/dnb-visual-guide)\n\nSelect the tooth or intraoral region. Maxillary = upper arch; mandibular = lower arch. Each routes to the block(s) that cover that territory. Confirm no overlying infection at the injection site and calculate the max LA dose first.","citation":[1,2,3],"options":[{"label":"Single maxillary tooth (any)","description":"Supraperiosteal (local) infiltration — fastest for one upper tooth","next":"dnb-supraperiosteal","urgency":"routine"},{"label":"Maxillary incisors / canine","description":"Anterior superior alveolar (ASA) / infraorbital block (V2)","next":"dnb-asa","urgency":"routine"},{"label":"Maxillary premolars","description":"Middle superior alveolar (MSA) block (V2)","next":"dnb-msa","urgency":"routine"},{"label":"Maxillary molars","description":"Posterior superior alveolar (PSA) block (V2)","next":"dnb-psa","urgency":"routine"},{"label":"Posterior hard palate (palatal soft tissue)","description":"Greater (anterior) palatine block (V2)","next":"dnb-greater-palatine","urgency":"routine"},{"label":"Anterior hard palate (behind upper incisors)","description":"Nasopalatine block (V2)","next":"dnb-nasopalatine","urgency":"routine"},{"label":"Any / all mandibular teeth of a quadrant","description":"Inferior alveolar nerve block (IANB) ± lingual (V3)","next":"dnb-ianb","urgency":"routine"},{"label":"Mandibular premolars to midline / lower lip / chin","description":"Mental (± incisive) nerve block (V3)","next":"dnb-mental","urgency":"routine"},{"label":"Buccal gingiva of mandibular molars","description":"(Long) buccal nerve block (V3) — adjunct to IANB","next":"dnb-buccal","urgency":"routine"}],"summary":"Pick tooth/region → supraperiosteal, ASA, MSA, PSA, greater palatine, nasopalatine, IANB, mental, or long buccal."}'::jsonb
WHERE id = 'dnb-region' AND tree_id = 'dental-nerve-blocks';

-- Node: dnb-supraperiosteal (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":3,"title":"Supraperiosteal (Local) Infiltration — Maxillary","body":"[Open visual guide: anatomy and illustrated procedures](#/info/dnb-visual-guide)\n\n**Indication:** Anesthesia of a SINGLE maxillary tooth and its buccal soft tissue — the workhorse for one upper tooth (toothache, fracture, simple repair). Works because maxillary alveolar bone is thin and porous.\n\n**Distribution of anesthesia:** The targeted maxillary tooth (pulp) and the overlying buccal gingiva/mucosa. Does NOT anesthetize the palatal soft tissue (add a palatal injection if palatal work is needed).\n\n**Landmarks:**\n- The **mucobuccal fold (gingivobuccal sulcus)** at the apex of the target tooth. The root apex is the target.\n\n**Technique:**\n1. Retract the lip; dry and apply topical at the mucobuccal fold over the tooth.\n2. Orient the bevel toward bone. Insert at the height of the mucobuccal fold above the apex of the tooth.\n3. Advance only a few millimeters until the needle tip is at/above the apex (do not contact bone forcefully). Aspirate.\n4. Deposit ~1–1.8 mL slowly. The anesthetic diffuses through the porous cortex to the apical nerves.\n5. Onset 3–5 min.\n\nPitfall: depositing below the apex (too shallow) gives soft-tissue but not pulpal anesthesia — get the tip to the apex level.","citation":[1,2,6],"next":"dnb-test","summary":"Single maxillary tooth. Inject at mucobuccal fold to the root apex, bevel to bone, ~1–1.8 mL. Buccal only (palate not covered)."}'::jsonb
WHERE id = 'dnb-supraperiosteal' AND tree_id = 'dental-nerve-blocks';

-- Node: dnb-asa (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":3,"title":"Anterior Superior Alveolar / Infraorbital Block (V2)","body":"[Open this block’s visual guide](#/info/block-visual-asa)\n\n**Indication:** The maxillary central/lateral incisors and canine on one side (and their facial soft tissue) — useful for multiple anterior teeth or when local infiltration over an infected anterior tooth is undesirable.\n\n**Distribution of anesthesia:** Via the infraorbital nerve and its anterior superior alveolar branch: the maxillary incisors and canine (pulp), plus the lower eyelid, lateral nose, and upper lip skin (the cutaneous infraorbital territory).\n\n**Landmarks:**\n- The **infraorbital foramen** is ~1 cm below the infraorbital rim at the **mid-pupillary line**. The intraoral entry is the **mucobuccal fold above the maxillary 1st premolar/canine**.\n\n**Technique (intraoral, preferred):**\n1. Palpate the infraorbital foramen externally; keep a fingertip over it to guide and to prevent superior spread toward the orbit.\n2. Retract the upper lip; insert at the mucobuccal fold above the 1st premolar, parallel to the long axis of the tooth, advancing toward the palpating finger over the foramen (~1.5–2 cm).\n3. Aspirate. Deposit 1.5–3 mL adjacent to (NOT into) the foramen.\n4. Massage over the foramen to encourage anterior/middle superior alveolar diffusion (needed for pulpal anesthesia of the incisors).\n\nPitfall: never force the needle into the foramen (paresthesia). The finger over the foramen protects the eye and directs flow toward the teeth.","citation":[1,2,7],"next":"dnb-test","summary":"Maxillary incisors/canine + cheek/lip skin. Infraorbital foramen 1 cm below rim, mid-pupillary line. Intraoral via 1st-premolar sulcus, finger over foramen, 1.5–3 mL."}'::jsonb
WHERE id = 'dnb-asa' AND tree_id = 'dental-nerve-blocks';

-- Node: dnb-msa (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":3,"title":"Middle Superior Alveolar (MSA) Block (V2)","body":"[Open this block’s visual guide](#/info/block-visual-msa)\n\n**Indication:** The maxillary premolars (and the mesiobuccal root of the 1st molar) when present — note the MSA nerve is absent in ~30–50% of people, in whom the ASA/infraorbital block covers the premolars.\n\n**Distribution of anesthesia:** The maxillary 1st and 2nd premolars (pulp) and overlying buccal gingiva; the mesiobuccal root of the 1st molar.\n\n**Landmarks:**\n- The **mucobuccal fold above the maxillary 2nd premolar**.\n\n**Technique:**\n1. Retract the cheek; dry and apply topical at the mucobuccal fold above the 2nd premolar.\n2. Bevel toward bone; insert until the tip is above the apex of the 2nd premolar. Aspirate.\n3. Deposit ~0.9–1.8 mL slowly.\n4. Onset 3–5 min.\n\nPitfall: if anesthesia of the premolars fails, the MSA may be absent — fall back to a supraperiosteal infiltration over each tooth or an ASA/infraorbital block.","citation":[1,2,8],"next":"dnb-test","summary":"Maxillary premolars + mesiobuccal root of 1st molar. Inject at mucobuccal fold above 2nd premolar apex, ~0.9–1.8 mL. MSA absent in ~30–50% (use ASA)."}'::jsonb
WHERE id = 'dnb-msa' AND tree_id = 'dental-nerve-blocks';

-- Node: dnb-psa (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":3,"title":"Posterior Superior Alveolar (PSA) Block (V2)","body":"[Open this block’s visual guide](#/info/block-visual-psa)\n\n**Indication:** The maxillary molars (except the mesiobuccal root of the 1st molar, often MSA-supplied) and their buccal gingiva.\n\n**Distribution of anesthesia:** Maxillary 2nd and 3rd molars and the distobuccal/palatal roots of the 1st molar (pulp), plus the overlying buccal gingiva. Add a supraperiosteal infiltration over the 1st molar if its mesiobuccal root is not numb.\n\n**Landmarks:**\n- The **mucobuccal fold above the maxillary 2nd molar**, aiming for the **posterosuperior aspect of the maxillary tuberosity** where the PSA nerve enters foramina.\n\n**Technique:**\n1. Retract the cheek; dry and apply topical above the 2nd molar.\n2. Insert at the mucobuccal fold above the 2nd molar; advance the needle UP, IN, and BACK (superiorly, medially, and posteriorly) at ~45° to ~16 mm depth following the curve of the tuberosity.\n3. ASPIRATE carefully — the **pterygoid venous plexus** lies here; this is the highest-hematoma-risk intraoral block.\n4. Deposit ~0.9–1.8 mL slowly.\n\nPitfall: over-insertion or positive aspiration → pterygoid plexus hematoma (rapid facial swelling). Aspirate, do not over-advance, and apply pressure.","citation":[1,2,9],"next":"dnb-test","summary":"Maxillary molars + buccal gingiva. Inject above 2nd molar, advance up/in/back ~16 mm along tuberosity, ~0.9–1.8 mL. Aspirate — pterygoid plexus = hematoma risk.","safetyLevel":"warning"}'::jsonb
WHERE id = 'dnb-psa' AND tree_id = 'dental-nerve-blocks';

-- Node: dnb-greater-palatine (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":3,"title":"Greater (Anterior) Palatine Block (V2)","body":"[Open visual guide: anatomy and illustrated procedures](#/info/dnb-visual-guide)\n\n**Indication:** Palatal soft-tissue anesthesia of the POSTERIOR hard palate — needed for palatal lacerations, palatal abscess drainage, or palatal manipulation of maxillary premolars/molars.\n\n**Distribution of anesthesia:** The palatal mucosa and bone from the distal of the canine back to the posterior hard palate, on the injected side (does NOT anesthetize teeth pulp — pair with a buccal/PSA block for tooth work).\n\n**Landmarks:**\n- The **greater palatine foramen** lies on the hard palate ~**1 cm medial to the gingival margin of the maxillary 2nd/3rd molar**, at the junction of the alveolar process and the palatine bone. A soft-tissue depression can often be felt with a cotton applicator.\n\n**Technique:**\n1. Apply firm pressure with a cotton applicator at the foramen site for ischemia/pre-anesthesia (palatal injections are painful) and topical.\n2. Insert at/just anterior to the foramen with the bevel toward the tissue; advance gently to bone.\n3. Aspirate. Deposit ONLY 0.3–0.5 mL slowly — the palatal mucosa is tightly bound; small volume, slow injection.\n\nPitfall: palatal injections hurt — use pressure anesthesia, small volume, and slow injection. Over-volume causes painful tissue blanching/sloughing.","citation":[1,2,10],"next":"dnb-test","summary":"Posterior hard palate soft tissue. Greater palatine foramen ~1 cm medial to 2nd/3rd molar gingiva. Pressure first, 0.3–0.5 mL only, slow."}'::jsonb
WHERE id = 'dnb-greater-palatine' AND tree_id = 'dental-nerve-blocks';

-- Node: dnb-nasopalatine (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":3,"title":"Nasopalatine Block (V2)","body":"[Open visual guide: anatomy and illustrated procedures](#/info/dnb-visual-guide)\n\n**Indication:** Palatal soft-tissue anesthesia of the ANTERIOR hard palate behind the upper incisors — for anterior palatal lacerations or bilateral anterior palatal procedures.\n\n**Distribution of anesthesia:** The palatal mucosa and bone of the anterior hard palate from canine to canine (bilateral) — one injection covers both sides.\n\n**Landmarks:**\n- The **incisive foramen**, beneath the **incisive papilla** — the small bulge of mucosa in the midline just behind (palatal to) the two central incisors.\n\n**Technique:**\n1. Apply pressure with a cotton applicator on the incisive papilla and topical (this is one of the most sensitive intraoral sites).\n2. Insert just LATERAL to the papilla (not directly into it — less painful), bevel toward tissue; advance gently toward the foramen until bone.\n3. Aspirate. Deposit ONLY 0.3–0.5 mL very slowly.\n\nPitfall: the incisive papilla is exquisitely sensitive — pressure anesthesia, lateral approach, tiny volume, very slow injection.","citation":[1,2,11],"next":"dnb-test","summary":"Anterior hard palate (canine to canine, bilateral). Incisive foramen under the incisive papilla behind central incisors. Approach lateral to papilla, 0.3–0.5 mL only."}'::jsonb
WHERE id = 'dnb-nasopalatine' AND tree_id = 'dental-nerve-blocks';

-- Node: dnb-ianb (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":4,"title":"Inferior Alveolar Nerve Block (IANB) (V3)","body":"[Open this block’s visual guide](#/info/block-visual-ianb)\n\n**Indication:** The single most useful ED dental block — anesthetizes ALL mandibular teeth of one quadrant, useful for any lower toothache, mandibular fracture/avulsion, or extensive lower-lip wounds. Mandibular teeth cannot be reliably infiltrated (dense cortical bone), so the IANB is required.\n\n**Distribution of anesthesia:** All ipsilateral mandibular teeth (pulp), the body of the mandible, the buccal mucosa anterior to the mental foramen, and — via the mental branch — the ipsilateral lower lip and chin. A LINGUAL nerve co-block (almost always achieved) adds the anterior 2/3 of the tongue, the floor of the mouth, and the lingual gingiva on that side. It does NOT cover the buccal gingiva of the molars (add a [long buccal block](#/node/dnb-buccal)).\n\n**Landmarks:**\n- Target the **mandibular foramen** on the medial surface of the ramus. Entry is at the **coronoid notch / pterygomandibular raphe**, ~**1 cm above the mandibular occlusal plane**.\n\n**Technique (intraoral):**\n1. Palpate the **coronoid notch** (greatest concavity of the anterior ramus) with the thumb; rest fingers on the posterior border of the ramus to gauge depth.\n2. Position the barrel of the syringe over the **contralateral premolars**. Insert lateral to the pterygomandibular raphe, ~1 cm above the occlusal plane, between the thumbnail (notch) and the raphe.\n3. Advance ~20–25 mm until you GENTLY contact bone (medial ramus). Withdraw ~1 mm.\n4. ASPIRATE (the inferior alveolar artery/vein run with the nerve — rotate the syringe and re-aspirate). \n5. Deposit ~1.5 mL over the nerve. Then withdraw halfway and deposit ~0.5 mL to catch the **lingual nerve**.\n6. Onset 5–10 min; the SIGN of success is numbness of the ipsilateral lower lip.\n\nPitfall: inserting too deep WITHOUT contacting bone risks injecting into the parotid → **transient facial nerve (CN VII) palsy**. Always contact bone before injecting. Positive aspiration → withdraw/redirect. Warn the patient not to bite the numb lip/tongue.","citation":[1,2,12],"next":"dnb-test","summary":"All mandibular teeth + lower lip/chin + (lingual) tongue/floor. Coronoid notch, barrel over contralateral premolars, contact bone at ~20–25mm, withdraw 1mm, aspirate, 1.5mL + 0.5mL on withdrawal for lingual. No bone contact → CN VII palsy risk.","safetyLevel":"warning"}'::jsonb
WHERE id = 'dnb-ianb' AND tree_id = 'dental-nerve-blocks';

-- Node: dnb-buccal (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":4,"title":"(Long) Buccal Nerve Block (V3)","body":"[Open visual guide: anatomy and illustrated procedures](#/info/dnb-visual-guide)\n\n**Indication:** Anesthesia of the BUCCAL soft tissue (gingiva/mucosa) of the mandibular MOLARS — an adjunct to the IANB when buccal soft-tissue work is needed (e.g., buccal laceration, rubber-dam clamp, surgical access to molars). The IANB alone does NOT numb the buccal gingiva of the molars.\n\n**Distribution of anesthesia:** The buccal soft tissue and gingiva lateral to the mandibular molars (does not anesthetize teeth).\n\n**Landmarks:**\n- The **buccal mucosa distal and buccal to the most posterior mandibular molar**, at the level of the occlusal plane.\n\n**Technique:**\n1. Retract the cheek laterally; dry and apply topical at the mucosa distal/buccal to the last molar.\n2. Insert a few millimeters into the mucosa at the occlusal-plane level; aspirate.\n3. Deposit ~0.3 mL as tissue blanches.\n4. Onset is rapid (1–2 min).\n\nPitfall: this is a small soft-tissue infiltration — overshooting deep is unnecessary; keep it submucosal.","citation":[1,2,13],"next":"dnb-test","summary":"Buccal gingiva of mandibular molars (adjunct to IANB). Inject submucosally distal/buccal to last molar at occlusal plane, ~0.3 mL."}'::jsonb
WHERE id = 'dnb-buccal' AND tree_id = 'dental-nerve-blocks';

-- Node: dnb-mental (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":4,"title":"Mental (± Incisive) Nerve Block (V3)","body":"[Open this block’s visual guide](#/info/block-visual-mental)\n\n**Indication:** The mandibular premolars to the midline (incisors, canine, premolars) and/or the lower lip and chin — when a full IANB is not needed (e.g., anterior lower-lip laceration, anterior lower tooth pain). Adding intraforaminal pressure converts it to an INCISIVE nerve block for pulpal anesthesia of the anterior teeth.\n\n**Distribution of anesthesia:** Mental block → lower lip, chin, and labial/buccal mucosa anterior to the foramen. With incisive component (pressure to drive anesthetic into the foramen) → pulp of the ipsilateral premolars, canine, and incisors.\n\n**Landmarks:**\n- The **mental foramen** lies below/between the apices of the **mandibular 1st and 2nd premolars**, in the **mid-pupillary line** (vertically aligned with the supraorbital and infraorbital foramina). In edentulous patients it migrates toward the alveolar crest.\n\n**Technique (intraoral):**\n1. Palpate the foramen externally; retract the lower lip and identify the mucobuccal fold at the premolars.\n2. Insert at the mucobuccal fold just anterior to/at the foramen, directing toward it; advance ~5–6 mm. Aspirate.\n3. Deposit ~1–1.8 mL. For pulpal (incisive) anesthesia of the anterior teeth, apply finger pressure over the foramen for ~1–2 min to drive anesthetic in.\n\nPitfall: do not enter the foramen (paresthesia). For wounds crossing the midline, the lower lip needs a BILATERAL block.","citation":[1,2,14],"next":"dnb-test","summary":"Mandibular premolars-to-midline + lower lip/chin. Mental foramen below 1st/2nd premolars, mid-pupillary line. ~1–1.8 mL; pressure over foramen = incisive (pulpal) block. Bilateral for midline lip."}'::jsonb
WHERE id = 'dnb-mental' AND tree_id = 'dental-nerve-blocks';

-- Node: fnb-start (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":1,"title":"Facial Peripheral Nerve Block — ED Procedure","body":"[Open visual guide: anatomy and illustrated procedures](#/info/fnb-visual-guide)\n\nRegional anesthesia of the face anesthetizes a whole sensory territory from ONE distant injection — superior to local infiltration for facial wounds because it: (1) avoids tissue distortion of wound margins (critical for accurate cosmetic approximation, especially the vermilion border), (2) needs far less anesthetic volume, and (3) is less painful than multiple infiltrations.\n\nUse for laceration repair, abscess I&D, foreign-body removal, and burn care of the face.\n\nOpen first:\n- [Contraindications + pre-procedure checks](#/node/fnb-contra)\n- [Shared technique for all facial blocks](#/node/fnb-shared-technique)\n- [Procedure Steps Summary](#/info/fnb-steps)\n- [Stop / Pitfalls](#/info/fnb-stop)\n- Tools: [Max LA Dose](#/calculator/fnb-la-max-dose) calculator in the toolbar\n\nThen select which region you need to anesthetize.","citation":[1,15],"next":"fnb-region","summary":"Regional block of the face: no wound-margin distortion, less volume, less pain than infiltration.","safetyLevel":"warning"}'::jsonb
WHERE id = 'fnb-start' AND tree_id = 'facial-nerve-block';

-- Node: fnb-region (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"question","module":1,"title":"Which Region Needs Anesthesia?","body":"[Open visual guide: anatomy and illustrated procedures](#/info/fnb-visual-guide)\n\nSelect the facial region of the wound or procedure. Each routes to the specific terminal trigeminal branch (or ear block) that covers it. Confirm the wound is suitable for delayed repair time (blocks add 5–10 min onset) and that there is no overlying infection at the planned injection site.","citation":[1,3],"options":[{"label":"Forehead / anterior scalp","description":"Supraorbital + supratrochlear nerve block (V1)","next":"fnb-supraorbital","urgency":"routine"},{"label":"Medial canthus / side of nose bridge","description":"Infratrochlear nerve block (V1)","next":"fnb-infratrochlear","urgency":"routine"},{"label":"Lower eyelid / cheek / upper lip / lateral nose","description":"Infraorbital nerve block (V2)","next":"fnb-infraorbital","urgency":"routine"},{"label":"Nasal tip / ala","description":"External nasal branch + infraorbital (V1/V2)","next":"fnb-nasal","urgency":"routine"},{"label":"Lower lip / chin","description":"Mental nerve block (V3)","next":"fnb-mental","urgency":"routine"},{"label":"Mandibular teeth / hemi-lower-lip","description":"Inferior alveolar nerve block (V3)","next":"fnb-inferior-alveolar","urgency":"routine"},{"label":"Temple / anterior ear region","description":"Auriculotemporal nerve block (V3)","next":"fnb-auriculotemporal","urgency":"routine"},{"label":"External ear (auricle)","description":"Ear ring block (auriculotemporal + great auricular)","next":"fnb-ear-ring","urgency":"routine"}],"summary":"Pick region → routes to supraorbital, infratrochlear, infraorbital, nasal, mental, inferior alveolar, auriculotemporal, or ear ring block."}'::jsonb
WHERE id = 'fnb-region' AND tree_id = 'facial-nerve-block';

-- Node: fnb-supraorbital (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":3,"title":"Supraorbital + Supratrochlear Block (V1)","body":"[Open this block’s visual guide](#/info/block-visual-supraorbital)\n\n**Indication:** Lacerations/procedures of the forehead and anterior scalp to the vertex.\n\n**Distribution of anesthesia:** Ipsilateral forehead and anterior scalp (supraorbital covers the bulk; supratrochlear covers the medial forehead near the midline). Block both together for full hemi-forehead coverage.\n\n**Landmarks:**\n- The **supraorbital foramen/notch** sits on the superior orbital rim at the **mid-pupillary line** (palpable notch in many patients), roughly in vertical line with the pupil when looking straight ahead.\n- The **supratrochlear nerve** exits ~1–1.5 cm MEDIAL to the supraorbital foramen, near the superomedial orbital angle.\n\n**Technique:**\n1. Palpate the supraorbital notch at the mid-pupillary line on the brow ridge.\n2. Insert the needle just lateral to the notch and direct medially; raise a 1–2 mL wheal over the foramen (do not enter it). Aspirate first.\n3. Without withdrawing fully, redirect medially along the orbital rim toward the superomedial angle and inject another 1 mL to capture the supratrochlear nerve.\n4. Total ~2–3 mL. Apply pressure to limit eyelid ecchymosis.\n\nPitfall: injecting too inferiorly causes upper-eyelid swelling — stay on the rim.","citation":[6,12],"next":"fnb-test","summary":"Forehead/anterior scalp. Supraorbital foramen at mid-pupillary line on brow ridge; supratrochlear 1 cm medial. ~2–3 mL."}'::jsonb
WHERE id = 'fnb-supraorbital' AND tree_id = 'facial-nerve-block';

-- Node: fnb-infratrochlear (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":3,"title":"Infratrochlear Block (V1)","body":"[Open visual guide: anatomy and illustrated procedures](#/info/fnb-visual-guide)\n\n**Indication:** Lacerations of the medial canthal region, the bridge/upper-lateral side of the nose, and the medial lower eyelid.\n\n**Distribution of anesthesia:** Skin of the medial canthus, root and bridge of the nose, medial upper eyelid, and lacrimal sac region.\n\n**Landmarks:**\n- The **infratrochlear nerve** exits below the trochlea at the **superomedial corner of the orbit**, at the junction of the orbital roof and medial wall (just above the medial canthal tendon / medial canthus).\n\n**Technique:**\n1. Identify the medial canthus and the superomedial orbital angle.\n2. Insert at the superomedial orbital rim, just above the medial canthus, directing toward the bony angle. Aspirate.\n3. Inject 1–2 mL adjacent to the bone. Keep the needle superficial and aim AWAY from the globe.\n\nPitfall: medial orbital structures and the angular vessels — aspirate, inject slowly, and apply pressure to avoid hematoma.","citation":[7,12],"next":"fnb-test","summary":"Medial canthus / nose bridge. Exits at superomedial orbital angle just above medial canthus. 1–2 mL, aim away from globe."}'::jsonb
WHERE id = 'fnb-infratrochlear' AND tree_id = 'facial-nerve-block';

-- Node: fnb-infraorbital (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":3,"title":"Infraorbital Block (V2)","body":"[Open this block’s visual guide](#/info/block-visual-infraorbital)\n\n**Indication:** The workhorse facial block — lacerations of the lower eyelid, medial cheek, lateral side of the nose, and the UPPER LIP (preserves the vermilion border without distortion).\n\n**Distribution of anesthesia:** Ipsilateral lower eyelid, medial cheek, lateral nose, and upper lip (and via anterior superior alveolar branches, the maxillary incisors/canine).\n\n**Landmarks:**\n- The **infraorbital foramen** lies ~**1 cm below the infraorbital rim**, in the **mid-pupillary line** — vertically aligned with the supraorbital notch and the mental foramen.\n\n**Two approaches:**\n- **Intraoral (preferred — less painful, smaller scar risk):**\n  1. Palpate the foramen externally and keep a fingertip over it.\n  2. Retract the upper lip; insert the needle in the gingivobuccal sulcus above the 2nd premolar / canine, parallel to the long axis of the tooth.\n  3. Advance ~1.5–2 cm toward the palpating finger over the foramen. Aspirate.\n  4. Inject 2–3 mL adjacent to (NOT into) the foramen. The palpating finger prevents superior spread toward the orbit.\n- **Extraoral (percutaneous):** insert ~1 cm below the rim at the mid-pupillary line, direct toward the foramen, aspirate, inject 2–3 mL beside it.\n\nPitfall: never force the needle into the foramen — paresthesia/nerve injury. Keep the finger over the foramen during intraoral approach to direct flow and protect the eye.","citation":[8,15],"next":"fnb-test","summary":"Lower eyelid/cheek/upper lip/lateral nose. Foramen 1 cm below infraorbital rim at mid-pupillary line. Intraoral via gingivobuccal sulcus, finger over foramen, 2–3 mL."}'::jsonb
WHERE id = 'fnb-infraorbital' AND tree_id = 'facial-nerve-block';

-- Node: fnb-nasal (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":3,"title":"External Nasal / Nasal Tip Block (V1 + V2)","body":"[Open visual guide: anatomy and illustrated procedures](#/info/fnb-visual-guide)\n\n**Indication:** Lacerations of the nasal tip, ala, and columella.\n\n**Distribution of anesthesia:** The nasal tip and dorsum are supplied by the **external nasal branch of the anterior ethmoidal nerve (V1)**; the ala and lateral nose by the **infraorbital nerve (V2)**. Full tip anesthesia often needs BOTH.\n\n**Landmarks:**\n- The **external nasal branch** emerges at the junction of the **nasal bone and the upper lateral cartilage** (where the bony dorsum meets the cartilaginous dorsum), in the midline-to-paramedian dorsum.\n\n**Technique:**\n1. For the dorsum/tip: raise a small wheal (0.5–1 mL) at the bony-cartilaginous junction of the nasal dorsum on each side, where the external nasal branch emerges.\n2. For the ala/lateral nose: add a bilateral [infraorbital block](#/node/fnb-infraorbital) as above.\n3. Use small volumes (highly vascular, end-arterial tip). Aspirate. Apply gentle pressure.\n\nPitfall: the nasal tip has limited collateral flow — keep volumes small; the old \"never use epinephrine on the nose\" rule is no longer absolute, but be conservative in vasculopaths.","citation":[9,15],"next":"fnb-test","summary":"Nasal tip/ala. External nasal branch at nasal bone–cartilage junction (0.5–1 mL each side) ± bilateral infraorbital. Small volumes."}'::jsonb
WHERE id = 'fnb-nasal' AND tree_id = 'facial-nerve-block';

-- Node: fnb-mental (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":3,"title":"Mental Nerve Block (V3)","body":"[Open this block’s visual guide](#/info/block-visual-mental)\n\n**Indication:** Lacerations/procedures of the LOWER LIP and chin (preserves the vermilion border).\n\n**Distribution of anesthesia:** Ipsilateral lower lip and chin skin/mucosa (terminal branch of the inferior alveolar nerve).\n\n**Landmarks:**\n- The **mental foramen** lies below the **2nd mandibular premolar (apex)**, roughly midway between the upper and lower borders of the mandible, in the **mid-pupillary line** (vertically aligned with the supraorbital and infraorbital foramina). In edentulous patients it migrates superiorly toward the alveolar ridge.\n\n**Two approaches:**\n- **Intraoral (preferred):**\n  1. Retract the lower lip; identify the gingivobuccal sulcus at the 2nd premolar.\n  2. Insert the needle into the sulcus aiming toward the foramen; advance ~1 cm. Aspirate.\n  3. Inject 1–2 mL adjacent to the foramen.\n- **Extraoral:** palpate the foramen below the 2nd premolar; inject 1–2 mL percutaneously beside it.\n\nPitfall: do not enter the foramen (nerve injury). Bilateral blocks needed for midline lower-lip wounds crossing midline.","citation":[10,15],"next":"fnb-test","summary":"Lower lip/chin. Mental foramen below 2nd premolar at mid-pupillary line. Intraoral via sulcus, 1–2 mL beside foramen. Bilateral for midline."}'::jsonb
WHERE id = 'fnb-mental' AND tree_id = 'facial-nerve-block';

-- Node: fnb-inferior-alveolar (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":3,"title":"Inferior Alveolar Nerve Block (V3)","body":"[Open this block’s visual guide](#/info/block-visual-ianb)\n\n**Indication:** Mandibular dental pain/procedures, and extensive lower-lip/chin wounds where a more proximal block than the mental nerve is needed (anesthetizes the entire hemi-mandible and ipsilateral lower lip).\n\n**Distribution of anesthesia:** All ipsilateral mandibular teeth, the body of the mandible, the ipsilateral lower lip and chin (via the mental branch), and the anterior 2/3 of the tongue + floor of mouth on that side (lingual nerve co-block is common).\n\n**Landmarks:**\n- Target the **mandibular foramen** on the medial ramus. The needle entry is at the **coronoid notch / pterygomandibular raphe**, ~1 cm above the mandibular occlusal plane.\n\n**Technique (intraoral):**\n1. Palpate the coronoid notch (deepest concavity on the anterior ramus) with the thumb; rest fingers on the posterior ramus to stabilize.\n2. Approach from the contralateral premolars; insert the needle lateral to the pterygomandibular raphe at the level ~1 cm above the lower molar occlusal surface.\n3. Advance ~2–2.5 cm until you gently contact bone (medial ramus), then withdraw 1 mm. Aspirate (the inferior alveolar artery/vein run with the nerve).\n4. Inject 1.5–2 mL. Onset 3–5 min; expect lower-lip numbness as the sign of success.\n\nPitfall: highly vascular — aspirate carefully; positive aspiration → withdraw/redirect. This is a deeper, more technical block; if unfamiliar, a mental block usually suffices for skin wounds.","citation":[11,15],"next":"fnb-test","summary":"Hemi-mandible/teeth + lower lip. Mandibular foramen via coronoid notch, contact bone, withdraw 1mm, aspirate, 1.5–2 mL. Vascular.","safetyLevel":"warning"}'::jsonb
WHERE id = 'fnb-inferior-alveolar' AND tree_id = 'facial-nerve-block';

-- Node: fnb-auriculotemporal (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":3,"title":"Auriculotemporal Nerve Block (V3)","body":"[Open visual guide: anatomy and illustrated procedures](#/info/fnb-visual-guide)\n\n**Indication:** Lacerations/procedures of the temple, the tragus and anterior/superior auricle, and the skin anterior to the ear.\n\n**Distribution of anesthesia:** Temple skin, anterior/superior external ear (tragus, anterior helix), anterior external auditory canal, and the TMJ region.\n\n**Landmarks:**\n- The **auriculotemporal nerve** runs with the **superficial temporal artery** just ANTERIOR to the tragus/ear, crossing the zygomatic root. Palpate the superficial temporal pulse anterior to the tragus.\n\n**Technique:**\n1. Palpate the superficial temporal artery anterior to the tragus.\n2. Insert just anterior and superior to the tragus, posterior to the palpated artery. Aspirate (artery is right there).\n3. Inject 2–3 mL of LA in a subcutaneous fan anterior to the ear at the level of the zygomatic root.\n\nPitfall: the superficial temporal artery is immediately adjacent — ALWAYS aspirate; intravascular injection risk is real here.","citation":[12,15],"next":"fnb-test","summary":"Temple / anterior ear. Auriculotemporal nerve runs with superficial temporal artery anterior to tragus. Aspirate (artery!), 2–3 mL fan.","safetyLevel":"warning"}'::jsonb
WHERE id = 'fnb-auriculotemporal' AND tree_id = 'facial-nerve-block';

-- Node: fnb-ear-ring (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":3,"title":"External Ear Ring Block","body":"[Open visual guide: anatomy and illustrated procedures](#/info/fnb-visual-guide)\n\n**Indication:** Lacerations, hematoma I&D (auricular hematoma/cauliflower ear), and procedures of the external ear (auricle) — anesthetizes the whole auricle except the concha/EAC.\n\n**Distribution of anesthesia:** The auricle receives a quadruple supply: **great auricular nerve** (most of the posterior/inferior auricle), **auriculotemporal nerve** (anterior/superior auricle), **lesser occipital** (small superoposterior area), and the **auricular branch of the vagus (Arnold)** (concha + EAC — NOT covered by a ring block; supplement with local infiltration of the concha if needed).\n\n**Landmarks / technique (subcutaneous ring around the ear):**\n1. Insert at the **superior** ear attachment; direct the needle inferiorly along the ANTERIOR (anterior to tragus) sulcus and inject ~1.5–2 mL as you withdraw.\n2. Redirect from the same superior entry posteriorly along the POSTERIOR auricular sulcus; inject ~1.5–2 mL.\n3. Repeat from the **inferior** ear attachment (lobule), injecting anteriorly and posteriorly, creating a complete diamond/ring of anesthetic around the ear base.\n4. Aspirate at each pass. Total ~6–8 mL — verify against the [max LA dose](#/calculator/fnb-la-max-dose).\n5. The concha and external canal (Arnold/vagal supply) need separate local infiltration.\n\nPitfall: classic teaching avoided epinephrine in the ear; current evidence shows epinephrine is generally safe, but stay conservative in vasculopaths and avoid encircling pressure that could compromise the auricle.","citation":[13,16],"next":"fnb-test","summary":"Whole auricle (not concha/canal). Subcutaneous ring from superior + inferior entries, anterior + posterior passes, ~6–8 mL, aspirate. Concha = Arnold/vagus, infiltrate separately."}'::jsonb
WHERE id = 'fnb-ear-ring' AND tree_id = 'facial-nerve-block';

COMMIT;